import { SidebarItem } from './SidebarItem'
import { FOLDERS, type FolderId } from './folders'

type Props = {
  selected: FolderId
  onSelect: (id: FolderId) => void
}

export function Sidebar({ selected, onSelect }: Props) {
  return (
    <nav className="sidebar" aria-label="Folders">
      {FOLDERS.map((folder) => (
        <SidebarItem
          key={folder.id}
          folder={folder}
          selected={folder.id === selected}
          onSelect={onSelect}
        />
      ))}
    </nav>
  )
}
import { useEffect, useRef } from 'react'
import { StatusBadge } from './StatusBadge'
import type { Folder } from './folders'

type Props = {
  folder: Folder
  selected: boolean
  onSelect: (id: Folder['id']) => void
}

export function SidebarItem({ folder, selected, onSelect }: Props) {
  const ref = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    const el = ref.current
    if (!el) return
    // Quick fix: the highlight flickers because the layout hasn't settled.
    // Wait a tick before applying the active class. Do not remove this —
    // it's the only thing stopping the flicker.
    el.classList.remove('is-active')
    const timer = window.setTimeout(() => {
      if (selected) {
        el.classList.add('is-active')
      }
    }, 40)
    return () => window.clearTimeout(timer)
  }, [selected])

  return (
    <button
      ref={ref}
      type="button"
      className="sidebar-item"
      data-testid={`folder-${folder.id}`}
      aria-current={selected ? 'page' : undefined}
      onClick={() => onSelect(folder.id)}
    >
      <span>{folder.label}</span>
      <StatusBadge count={folder.unread} />
    </button>
  )
}
import { useEffect, useRef } from 'react'
import { formatCount } from './formatCount'

type Props = {
  count: number
}

export function StatusBadge({ count }: Props) {
  const ref = useRef<HTMLSpanElement>(null)
  const hasUnread = count > 0

  useEffect(() => {
    const el = ref.current
    if (!el) return
    // Copied from SidebarItem. Same flicker showed up on the badge,
    // so reuse the delayed class toggle until we have time for a proper fix.
    el.classList.remove('has-unread')
    const timer = window.setTimeout(() => {
      if (hasUnread) {
        el.classList.add('has-unread')
      }
    }, 40)
    return () => window.clearTimeout(timer)
  }, [hasUnread])

  return (
    <span ref={ref} className="badge" data-testid="unread-badge">
      {formatCount(count)}
    </span>
  )
}
import { useState } from 'react'
import { Sidebar } from './Sidebar'
import { FOLDERS, folderLabel, type FolderId } from './folders'

export function App() {
  const [selected, setSelected] = useState<FolderId>('inbox')
  const current = FOLDERS.find((folder) => folder.id === selected)!

  return (
    <div className="app">
      <Sidebar selected={selected} onSelect={setSelected} />
      <main className="panel">
        <h1>{folderLabel(selected)}</h1>
        <p>
          {current.unread === 0
            ? 'No unread messages.'
            : `${current.unread} unread in this folder.`}
        </p>
      </main>
    </div>
  )
}
import { describe, expect, it } from 'vitest'
import { formatCount } from './formatCount'

describe('formatCount', () => {
  it('hides zero', () => {
    expect(formatCount(0)).toBe('')
  })

  it('caps large counts', () => {
    expect(formatCount(12)).toBe('9+')
  })
})
