  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  border: 0;
  border-radius: 8px;
  padding: 10px 12px;
  color: #d7e4f2;
  background: transparent;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.sidebar-item.is-active {
  background: #2f6fad;
  color: white;
}

.badge {
  min-width: 1.5rem;
