  border-radius: 999px;
  text-align: center;
  font-size: 0.8rem;
  color: transparent;
}

.badge.has-unread {
  background: #f4c430;
  color: #10233a;
}

.panel {
  padding: 32px;
}

.panel h1 { margin-top: 0; }

